C_detour_unless_longer.code:
def priority(state_a, state_b, id_a, id_b):
    detour_a = state_a['detour_from_optimal']
    detour_b = state_b['detour_from_optimal']
    optimal_a = state_a['optimal_route_cost']
    optimal_b = state_b['optimal_route_cost']

    # Check if one robot's original journey was more than twice as long
    if optimal_a > 2 * optimal_b:
        return id_a
    if optimal_b > 2 * optimal_a:
        return id_b

    # Otherwise, give way to whichever robot has been detoured more
    if detour_a > detour_b:
        return id_a
    else:
        return id_b

T_detour_cutoff.code:
def priority(state_a, state_b, id_a, id_b):
    detour_a = state_a['detour_from_optimal']
    detour_b = state_b['detour_from_optimal']

    # Check if one robot has been detoured by more than 2
    a_heavily_detoured = detour_a > 2
    b_heavily_detoured = detour_b > 2

    if a_heavily_detoured and not b_heavily_detoured:
        return id_a
    elif b_heavily_detoured and not a_heavily_detoured:
        return id_b
    else:
        # Both heavily detoured or neither heavily detoured
        # Give way to the one with shorter original journey
        if state_a['optimal_route_cost'] < state_b['optimal_route_cost']:
            return id_a
        elif state_b['optimal_route_cost'] < state_a['optimal_route_cost']:
            return id_b
        else:
            # If optimal costs are equal, use id as tiebreaker
            return id_a if id_a < id_b else id_b

