def priority(state_a, state_b, id_a, id_b):
    detour_a = state_a['detour_from_optimal']
    detour_b = state_b['detour_from_optimal']

    if detour_a > detour_b:
        return id_a
    elif detour_b > detour_a:
        return id_b

    constraints_a = state_a['constraints_on_this_robot']
    constraints_b = state_b['constraints_on_this_robot']

    if constraints_a > constraints_b:
        return id_a
    elif constraints_b > constraints_a:
        return id_b

    current_cost_a = state_a['current_route_cost']
    current_cost_b = state_b['current_route_cost']

    if current_cost_a > current_cost_b:
        return id_a
    elif current_cost_b > current_cost_a:
        return id_b

    return id_a
